use crate::OriginalReceivingPrimary;
use crate::RetainedWorkOutcome;
//! 🌳️ Native receiving projects genuine heterogeneous children without constructing an intermediate wire owner.
use crate::{DslValue,Number,NativeDecodeControl,RetirementDemand,ValueError,ValueRefusalKind,retirement::RetireOwned,retained_clone::{RetainedCloneBinding,RetainedCloneClose,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneRef,RetainedCloneStep,RetainedFieldCursor,RetainedCloneCursor,retained_clone_grant_admits}};
use super::{NativeReceive,NativeReceiver};
use std::mem::{ManuallyDrop,size_of};
#[derive(Clone,Copy,Debug,PartialEq,Eq)]
pub enum NativeTreeKind{Null,Bool,Number,Text,Array,Object}
impl NativeTreeKind{pub const fn as_str(self)->&'static str{match self{Self::Null=>"null",Self::Bool=>"bool",Self::Number=>"number",Self::Text=>"text",Self::Array=>"array",Self::Object=>"object"}}}
pub trait NativeValueSource:Sync+'static{
 fn as_source(&self)->&dyn NativeValueSource;
 fn tree_kind(&self)->Option<NativeTreeKind>;
 fn enum_ordinal(&self)->Result<u32,ValueError>{Err(invalid())}
 fn variant_tag(&self)->Option<&str>{None}
 fn variant_payload(&self)->Result<&dyn NativeValueSource,ValueError>{Err(invalid())}
 fn is_null(&self)->bool{false}
 fn boolean(&self)->Result<bool,ValueError>{Err(invalid())}
 fn number(&self)->Result<Number,ValueError>{Err(invalid())}
 fn text(&self)->Result<&String,ValueError>{Err(invalid())}
 fn record_len(&self)->Result<usize,ValueError>{Err(invalid())}
 fn record_key(&self,_index:usize)->Result<super::NativeRecordKey<'_>,ValueError>{Err(invalid())}
 fn record_name(&self,index:usize)->Result<&str,ValueError>{match self.record_key(index)?{super::NativeRecordKey::Name(name)=>Ok(name),super::NativeRecordKey::Ordinal(_)=>Err(invalid())}}
 fn record_entry(&self,_index:usize)->Result<&dyn NativeValueSource,ValueError>{Err(invalid())}
 fn record_child(&self,_index:usize)->Result<&dyn NativeValueSource,ValueError>{Err(invalid())}
 fn sequence_len(&self)->Result<usize,ValueError>{Err(invalid())}
 fn sequence_child(&self,_index:usize)->Result<&dyn NativeValueSource,ValueError>{Err(invalid())}
}
pub fn invalid()->ValueError{ValueError::literal(ValueRefusalKind::InvalidValue,"native receiving original type, field or phase is invalid")}
pub fn fixed(copy_bytes:usize)->RetirementDemand{RetirementDemand{copy_bytes,depth:1,..Default::default()}}
pub fn receipt(d:RetirementDemand)->RetainedCloneProgress{RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,retained_capacity_bytes:d.capacity_bytes,released_bytes:d.release_bytes}}
pub fn nested(mut d:RetirementDemand,copy:usize)->Result<RetirementDemand,ValueError>{d.copy_bytes=d.copy_bytes.checked_add(copy).ok_or_else(invalid)?;d.depth=d.depth.checked_add(1).ok_or_else(invalid)?;Ok(d)}
pub fn child_grant(g:RetainedCloneGrant,copy:usize)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes-copy,maximum_depth:g.maximum_depth-1,..g}}
pub fn add_receipt(mut p:RetainedCloneProgress,copy:usize)->Result<RetainedCloneProgress,ValueError>{p.copied_bytes=p.copied_bytes.checked_add(copy).ok_or_else(invalid)?;Ok(p)}
impl NativeValueSource for DslValue{
 fn as_source(&self)->&dyn NativeValueSource{self}
 fn tree_kind(&self)->Option<NativeTreeKind>{match self{Self::Null=>Some(NativeTreeKind::Null),Self::Bool(_)=>Some(NativeTreeKind::Bool),Self::Number(_)=>Some(NativeTreeKind::Number),Self::String(_)=>Some(NativeTreeKind::Text),Self::Array(_)=>Some(NativeTreeKind::Array),Self::Object(_)=>Some(NativeTreeKind::Object),_=>None}}
 fn is_null(&self)->bool{matches!(self,Self::Null)}
 fn boolean(&self)->Result<bool,ValueError>{match self{Self::Bool(value)=>Ok(*value),_=>Err(invalid())}}
 fn number(&self)->Result<Number,ValueError>{match self{Self::Number(value)=>Ok(*value),_=>Err(invalid())}}
 fn text(&self)->Result<&String,ValueError>{match self{Self::String(value)=>Ok(value),_=>Err(invalid())}}
 fn record_len(&self)->Result<usize,ValueError>{match self{Self::Object(entries)=>Ok(entries.len()),_=>Err(invalid())}}
 fn record_key(&self,index:usize)->Result<super::NativeRecordKey<'_>,ValueError>{match self{Self::Object(entries)=>entries.get(index).map(|(key,_)|super::NativeRecordKey::Name(key.as_str())).ok_or_else(invalid),_=>Err(invalid())}}
 fn record_entry(&self,index:usize)->Result<&dyn NativeValueSource,ValueError>{match self{Self::Object(entries)=>entries.get(index).map(|entry|entry as &dyn NativeValueSource).ok_or_else(invalid),_=>Err(invalid())}}
 fn record_child(&self,index:usize)->Result<&dyn NativeValueSource,ValueError>{match self{Self::Object(entries)=>entries.get(index).map(|(_,value)|value as &dyn NativeValueSource).ok_or_else(invalid),_=>Err(invalid())}}
 fn sequence_len(&self)->Result<usize,ValueError>{match self{Self::Array(entries)=>Ok(entries.len()),_=>Err(invalid())}}
 fn sequence_child(&self,index:usize)->Result<&dyn NativeValueSource,ValueError>{match self{Self::Array(entries)=>entries.get(index).map(|value|value as &dyn NativeValueSource).ok_or_else(invalid),_=>Err(invalid())}}
}
impl NativeValueSource for String{fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{Some(NativeTreeKind::Text)}fn text(&self)->Result<&String,ValueError>{Ok(self)}}
impl NativeValueSource for bool{fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{Some(NativeTreeKind::Bool)}fn boolean(&self)->Result<bool,ValueError>{Ok(*self)}}
impl NativeValueSource for u8{fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{Some(NativeTreeKind::Number)}fn number(&self)->Result<Number,ValueError>{Ok(Number::UInt(u64::from(*self)))}}
impl NativeValueSource for Number{fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{Some(NativeTreeKind::Number)}fn number(&self)->Result<Number,ValueError>{Ok(*self)}}
impl<T:NativeValueSource> NativeValueSource for (String,T){fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{Some(NativeTreeKind::Array)}fn variant_tag(&self)->Option<&str>{Some(&self.0)}fn variant_payload(&self)->Result<&dyn NativeValueSource,ValueError>{Ok(&self.1)}fn sequence_len(&self)->Result<usize,ValueError>{Ok(2)}fn sequence_child(&self,index:usize)->Result<&dyn NativeValueSource,ValueError>{match index{0=>Ok(&self.0),1=>Ok(&self.1),_=>Err(invalid())}}}
impl<T:NativeValueSource> NativeValueSource for Vec<T>{fn as_source(&self)->&dyn NativeValueSource{self}fn tree_kind(&self)->Option<NativeTreeKind>{Some(NativeTreeKind::Array)}fn sequence_len(&self)->Result<usize,ValueError>{Ok(self.len())}fn sequence_child(&self,index:usize)->Result<&dyn NativeValueSource,ValueError>{self.get(index).map(|value|value as &dyn NativeValueSource).ok_or_else(invalid)}}
pub struct NativeReceiveSlot<I:NativeValueSource+?Sized,T:NativeReceive<I>>{receiver:semio_framework_value_native_storage::NativeOwnedStorage<T::Receiver>,retired_header:Option<Box<T::Receiver>>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,closing:bool,subset:bool}
unsafe impl<I:NativeValueSource+?Sized,T:NativeReceive<I>> Send for NativeReceiveSlot<I,T>{}
impl<I:NativeValueSource+?Sized,T:NativeReceive<I>> Default for NativeReceiveSlot<I,T>{fn default()->Self{Self{receiver:semio_framework_value_native_storage::NativeOwnedStorage::empty(),retired_header:None,output:ManuallyDrop::new(None),retirement:Default::default(),closing:false,subset:false}}}
impl<I:NativeValueSource+?Sized,T:NativeReceive<I>> NativeReceiveSlot<I,T>{
 pub fn original_record_subset()->Self{let mut slot=Self::default();slot.subset=true;slot}
 pub fn ready(&self)->bool{!self.closing&&self.output.is_some()}
 pub fn demands(&self,input:RetainedCloneRef<'_,I>,body:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.output.is_some(){return Err(invalid())}if !self.receiver.reserved(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::reserve_demand())}if !self.receiver.initialized(){return Ok(semio_framework_value_native_storage::NativeOwnedStorage::<T::Receiver>::move_demand())}let receiver=self.receiver.get().ok_or_else(||ValueError::invariant("get target absent"))?;if receiver.output_ready(){nested(receiver.take_demand()?,0)}else{nested(receiver.demands(input,body)?,0)}}
 pub fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{let mut work=0;let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?;if !self.receiver.reserved(){let turn=self.receiver.reserve(g);let turn=control.receive_retained_work(g,turn);work=turn.work;return turn.result.map_err(Into::into)}if !self.receiver.initialized(){let turn=if self.subset{let Some(receiver)=T::record_subset_receiver()else{work=1;return Err(ValueError::literal(ValueRefusalKind::UnsupportedOwner,"native owner has no original record subset receiving port").with_retained_progress(RetainedCloneProgress{copied_items:1,..Default::default()}).into())};{let mut header=Some(receiver);self.receiver.put_from(&mut header,g)}}else{{let mut header=Some(T::receiver());self.receiver.put_from(&mut header,g)}};work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)}let receiver=self.receiver.get_mut().ok_or_else(||ValueError::invariant("get_mut target absent"))?;if receiver.output_ready(){let turn=receiver.take(child_grant(g,0));work=turn.work;let Some((value,p))=turn.result?else{return Ok(RetainedCloneStep::Progress(Default::default()))};*self.output=Some(value);return Ok(RetainedCloneStep::Complete(p))}let turn=receiver.advance(input,control,body,child_grant(g,0));work=turn.work;turn.result.map(|s|RetainedCloneStep::Progress(s.progress())).map_err(Into::into)})();RetainedWorkOutcome{result,work}}
 pub fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(T,RetainedCloneProgress)>>{if !self.ready()||!retained_clone_grant_admits(g,fixed(0)){return RetainedWorkOutcome{result:Ok(None),work:0}}let value=match self.output.take(){Some(v)=>v,None=>return RetainedWorkOutcome{result:Err(ValueError::invariant("output absent").into()),work:0}};RetainedWorkOutcome{result:Ok(Some((value,receipt(fixed(0))))),work:1}}
 pub fn begin_close(&mut self){self.closing=true;if let Some(receiver)=self.receiver.get_mut(){receiver.begin_close()}}
 pub fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(invalid())}if self.receiver.reserved()||self.retired_header.is_some(){return super::native_receiver_backing_demands::<I,T,_>(&self.receiver,&self.retired_header,body)}if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<T>(false,&None,body)}if self.output.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body)}Ok(Default::default())}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{if self.terminal_is_empty(){return Ok(RetainedCloneStep::Complete(Default::default()))}let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.receiver.reserved()||self.retired_header.is_some(){let turn=if let Some(receiver)=self.receiver.get_mut().filter(|receiver|!receiver.terminal_is_empty()){receiver.close_step(child_grant(g,0))}else{super::close_native_receiver_backing::<I,T,_>(&mut self.receiver,&mut self.retired_header,g)};work=turn.work;return turn.result.map(|s|RetainedCloneStep::Progress(s.progress()))}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);work=turn.work;return turn.result}if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,g);work=turn.work;return turn.result.map(|s|s.unwrap_or(RetainedCloneStep::Progress(Default::default())))}Ok(RetainedCloneStep::Complete(Default::default()))})();RetainedWorkOutcome{result,work}}
 pub fn terminal_is_empty(&self)->bool{self.receiver.terminal_is_empty()&&self.retired_header.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<I:NativeValueSource+?Sized,T:NativeReceive<I>> Drop for NativeReceiveSlot<I,T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native child receiving requires funded closure");}}
pub trait NativeScalarValue<I:NativeValueSource+?Sized>:RetireOwned{fn read(original:&I)->Result<Self,ValueError> where Self:Sized;fn read_copy_bytes(original:&I)->Result<usize,ValueError>;}
pub struct NativeScalarReceiver<I:NativeValueSource+?Sized,T:NativeScalarValue<I>>{binding:Option<RetainedCloneBinding>,output:ManuallyDrop<Option<T>>,retirement:RetainedCloneClose,closing:bool,taken:bool,input:std::marker::PhantomData<fn(&I)>}
impl<I:NativeValueSource+?Sized,T:NativeScalarValue<I>> NativeScalarReceiver<I,T>{pub fn new()->Self{Self{binding:None,output:ManuallyDrop::new(None),retirement:Default::default(),closing:false,taken:false,input:std::marker::PhantomData}}}
impl<I:NativeValueSource+?Sized,T:NativeScalarValue<I>> NativeReceiver<I,T> for NativeScalarReceiver<I,T>{
 fn demands(&self,input:RetainedCloneRef<'_,I>,_:usize)->Result<RetirementDemand,ValueError>{if self.closing||self.taken||self.output.is_some(){return Err(invalid());}if !input.check_binding(&self.binding)?{return Ok(fixed(input.binding_copy_bytes()));}Ok(fixed(T::read_copy_bytes(input.get())?))}
 fn advance(&mut self,input:RetainedCloneRef<'_,I>,control:&mut NativeDecodeControl<'_>,body:usize,g:RetainedCloneGrant)->RetainedWorkOutcome<RetainedCloneStep,OriginalReceivingPrimary>{let mut work=0;let result:Result<RetainedCloneStep,OriginalReceivingPrimary>=(||{let d=self.demands(input,body)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}control.checkpoint()?;crate::owned::receiving_capacity(control,d.capacity_bytes)?;let turn=input.bind(&mut self.binding,g);work=turn.work;if let Some(p)=turn.result?{control.receive_retained_work(g,RetainedWorkOutcome{result:Ok(RetainedCloneStep::Progress(p)),work:0}).result?;return Ok(RetainedCloneStep::Progress(p));}work=1;*self.output=Some(T::read(input.get())?);Ok(RetainedCloneStep::Complete(receipt(d)))})();RetainedWorkOutcome{result,work}}
 fn output_ready(&self)->bool{!self.closing&&self.output.is_some()}
 fn take_demand(&self)->Result<RetirementDemand,ValueError>{if !self.output_ready(){return Err(invalid());}Ok(fixed(0))}
 fn take(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome<Option<(T,RetainedCloneProgress)>>{let mut work=0;let result=(||{let d=self.take_demand()?;if !retained_clone_grant_admits(g,d){return Ok(None);}work=1;self.taken=true;Ok(Some((self.output.take().ok_or_else(invalid)?,receipt(d))))})();RetainedWorkOutcome{result,work}}
 fn begin_close(&mut self){self.closing=true;}
 fn close_demands(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.retirement.is_empty(){return self.retirement.next_owner_demands::<T>(false,&None,body);}if self.output.is_some(){return self.retirement.next_owner_demands::<T>(true,&None,body);}RetainedCloneBinding::close_demand(&self.binding,body)}
 fn close_step(&mut self,g:RetainedCloneGrant)->RetainedWorkOutcome{let mut work=0;let result=(||{let d=self.close_demands(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()));}if !self.retirement.is_empty(){let turn=self.retirement.step_granted(g);work=turn.work;return turn.result}if self.output.is_some(){let turn=self.retirement.begin_granted(&mut self.output,g);work=turn.work;return turn.result.map(|step|step.unwrap_or(RetainedCloneStep::Progress(Default::default())))}let turn=RetainedCloneBinding::close_one(&mut self.binding,g);work=turn.work;turn.result})();RetainedWorkOutcome{result,work}}
 fn terminal_is_empty(&self)->bool{self.binding.is_none()&&self.output.is_none()&&self.retirement.is_empty()}
}
impl<I:NativeValueSource+?Sized,T:NativeScalarValue<I>> Drop for NativeScalarReceiver<I,T>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"native scalar receiving requires funded closure");}}
macro_rules! scalar {($t:ty,$input:ident,$value:expr)=>{impl<I:NativeValueSource+?Sized> NativeScalarValue<I> for $t{fn read($input:&I)->Result<Self,ValueError>{$value}fn read_copy_bytes(_: &I)->Result<usize,ValueError>{Ok(size_of::<Self>())}}impl<I:NativeValueSource+?Sized> NativeReceive<I> for $t{type Receiver=NativeScalarReceiver<I,Self>;fn receiver()->Self::Receiver{Self::Receiver::new()}}};}
scalar!(bool,input,input.boolean());scalar!((),input,if input.is_null(){Ok(())}else{Err(invalid())});
scalar!(f64,input,{let n=input.number()?.as_f64();if n.is_finite(){Ok(n)}else{Err(invalid())}});
scalar!(f32,input,{let n=input.number()?.as_f64();if n.is_finite()&&n.abs()<=f32::MAX as f64{Ok(n as f32)}else{Err(invalid())}});
macro_rules! unsigned {($($t:ty),*)=>{$(scalar!($t,input,match input.number()?{Number::UInt(n)=><$t>::try_from(n).map_err(|_|invalid()),Number::Int(n)=><$t>::try_from(n).map_err(|_|invalid()),Number::Float(n)if n.is_finite()&&n.fract()==0.0&&n>=0.0&&(n as u128)<=<$t>::MAX as u128&&n<18446744073709551616.0=>Ok(n as $t),_=>Err(invalid())});)*};}
unsigned!(u8,u16,u32,u64,usize);
macro_rules! signed {($($t:ty),*)=>{$(scalar!($t,input,match input.number()?{Number::UInt(n)=><$t>::try_from(n).map_err(|_|invalid()),Number::Int(n)=><$t>::try_from(n).map_err(|_|invalid()),Number::Float(n)if n.is_finite()&&n.fract()==0.0&&n>=<$t>::MIN as f64&&n<=<$t>::MAX as f64&&n<9223372036854775808.0=>Ok(n as $t),_=>Err(invalid())});)*};}
